const speechPlayer=new SpeechPlayer({engine:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,onChange:updateSpeechControls,onError:error=>message(error==='unsupported'?'この端末では読み上げを使えません。':'読み上げを再生できませんでした。対応する音声が端末にあるか確認してください。')});
$('#modal').addEventListener('close',()=>speechPlayer.stop());
function updateSpeechControls(){for(const group of $$('[data-speech-key]')){const active=group.dataset.speechKey===speechPlayer.key,play=group.querySelector('[data-play]'),stop=group.querySelector('[data-stop]');const action=active?(speechPlayer.paused?'再開':'一時停止'):'再生';group.dataset.speechState=active?(speechPlayer.paused?'paused':'playing'):'idle';play.replaceChildren(icon(active&&!speechPlayer.paused?'pause':'play'));if(group.dataset.visibleSpeechLabel)play.append(el('span',group.dataset.visibleSpeechLabel+'を'+action));play.setAttribute('aria-label',group.dataset.speechLabel+(active?(speechPlayer.paused?'の読み上げを再開':'の読み上げを一時停止'):'を読み上げる'));play.title=group.dataset.speechLabel+'を'+action;stop.hidden=!active;}}
function speechControls(text,lang,key,labeled=false){const group=el('div',undefined,'speech-controls'),play=el('button'),stop=el('button');group.dataset.speechKey=key;if(labeled){group.classList.add('speech-controls-labeled');group.dataset.visibleSpeechLabel=catalog.languages.find(l=>l.code===lang)?.labelJa||lang;stop.append(el('span','停止'));}group.dataset.speechLabel=(catalog.languages.find(l=>l.code===lang)?.labelJa||lang)+'の文';play.dataset.play='';stop.dataset.stop='';play.append(icon('play'));stop.append(icon('stop'));stop.hidden=true;play.type=stop.type='button';play.setAttribute('aria-label',group.dataset.speechLabel+'を読み上げる');stop.setAttribute('aria-label',group.dataset.speechLabel+'の読み上げを停止');stop.title='停止';play.onclick=()=>speechPlayer.toggle(key,text,catalog.languages.find(l=>l.code===lang)?.speechCode||lang);stop.onclick=()=>speechPlayer.stop();group.append(play,stop);return group;}

function renderCaption(r){const old=records.get(r.id)||{};if((r.revision??0)<(old.revision??0))return;const next={...old,...r};if(!isDisplayableCaption(next))return;const view=sharedLanguage();const codes=room?.mode==='interpreter'?callCaptionLanguages($('#source-language').value):[...new Set(room?.mode==='face'?['ja',$('#face-self-language').value,$('#face-other-language').value,'en']:['ja',view,'en'])];const lines=codes.map(code=>({code,text:next.translations?.[code]||(code===next.source?next.text:'')})).filter(line=>line.text);if(!lines.length)return;const nearBottom=$('#captions').scrollHeight-$('#captions').scrollTop-$('#captions').clientHeight<100;let article=elements.get(r.id);if(!article){$('#captions .empty')?.remove();article=el('article',undefined,'caption');elements.set(r.id,article);$('#captions').append(article);}article.className='caption';article.replaceChildren();const meta=el('div',undefined,'caption-meta');meta.append(el('span',next.speaker||'参加者'));if(next.updating)meta.append(el('span','訳を更新中…','caption-progress'));if(next.memorySource)meta.append(el('span',next.memorySource==='spreadsheet'?'辞書の訳':'確認した訳','caption-memory'));if(next.id.startsWith(selfId+'_')&&next.source==='ja'&&next.status==='ready'&&!next.continuing&&!next.updating){const edit=el('button',undefined,'secondary');edit.type='button';edit.setAttribute('aria-label','日本語を直す');edit.title='日本語を直す';edit.append(icon('pen'));edit.onclick=()=>editJapanese(next);meta.append(edit);}if(next.continuing)meta.append(el('span','続きのことばを待っています','caption-progress'));if(next.source==='ja'&&next.status==='ready'&&!next.continuing&&!next.updating){const save=el('button',undefined,'secondary');save.type='button';save.setAttribute('aria-label','訳を確認して覚える');save.title='訳を確認して覚える';save.append(icon('book-medical'));save.onclick=()=>phraseCandidate(next);meta.append(save);}if(next.latencyMs)meta.title='翻訳処理 '+(next.latencyMs/1000).toFixed(1)+'秒';article.append(meta);for(const {code,text} of lines){const primaryCode=room?.mode==='face'?(next.speaker==='相手'?$('#face-self-language').value:$('#face-other-language').value):room?.mode==='interpreter'?$('#source-language').value:view;const line=el('div',undefined,'caption-line'+(code===primaryCode?' caption-line-primary':''));line.append(el('small',catalog.languages.find(l=>l.code===code)?.labelJa||code),el('p',text),speechControls(text,code,next.id+':'+code));article.append(line);}records.set(r.id,next);updateSpeechControls();if(nearBottom)$('#captions').scrollTop=$('#captions').scrollHeight;}
$('#text-form').onsubmit=e=>{e.preventDefault();const text=$('#text-input').value.trim();if(!text)return;const cap={...(room.mode==='face'?speakerCaption(faceSide,$('#face-self-language').value,$('#face-other-language').value):{}),type:'caption',id:crypto.randomUUID(),text,final:true};localTimings.set(cap.id,{kind:'text',sentAt:Date.now()});pending.set(cap.id,cap);if(submitCaption(cap))$('#text-input').value='';else message('再接続後に送信します。');};
function inviteLink(){const url=new URL(location.href);url.hash=new URLSearchParams({room:room.id,key:room.key,mode:room.mode}).toString();return url.href;}
function renderCallInvite(){const n=$('#call-invite');if(!room||room.mode!=='interpreter'||!room.creator){n.hidden=true;n.replaceChildren();return;}n.hidden=false;if(n.dataset.room===room.id)return;n.dataset.room=room.id;n.replaceChildren();const input=el('input');input.readOnly=true;input.value=inviteLink();input.setAttribute('aria-label','相手に送るリンク');const language=el('select');options(language,$('#source-language').value);language.onchange=()=>setSpeakingLanguage(language.value);n.append(label('じぶんが話すことば',language));const canvas=el('canvas');canvas.className='qr';canvas.setAttribute('aria-label','通話に参加するQRコード');n.append(canvas);void qrModule.then(m=>m?.drawQr(canvas,input.value)).catch(()=>{});const linkArea=el('div',undefined,'invite-link-area');const linkLabel=el('label','相手に送るリンク');input.id='call-invite-link';linkLabel.htmlFor=input.id;const row=el('div',undefined,'invite-link-row');const copy=el('button',undefined,'invite-copy');copy.type='button';copy.setAttribute('aria-label','リンクをコピー');copy.title='リンクをコピー';copy.append(icon('copy'));copy.onclick=async()=>{try{await navigator.clipboard.writeText(input.value);copy.replaceChildren(icon('check'));copy.setAttribute('aria-label','コピーしました');copy.title='コピーしました';setTimeout(()=>{copy.replaceChildren(icon('copy'));copy.setAttribute('aria-label','リンクをコピー');copy.title='リンクをコピー';},2000);}catch{input.select();message('招待リンクをコピーしてください。');}};row.append(input,copy);linkArea.append(linkLabel,row);n.append(linkArea);}
