async function sampleRtc(){for(const [id,p]of peers){try{const report=await p.pc.getStats();let pair;for(const v of report.values())if(v.type==='transport'&&v.selectedCandidatePairId)pair=report.get(v.selectedCandidatePairId);if(!pair)for(const v of report.values())if(v.type==='candidate-pair'&&v.state==='succeeded'&&v.nominated)pair=v;let lost=0,jitterMs=0;for(const v of report.values())if(v.type==='inbound-rtp'&&v.kind==='audio'){lost+=v.packetsLost||0;jitterMs=Math.max(jitterMs,(v.jitter||0)*1000);}if(pair)ledger.rtc(p.metricsId,{bytes:(pair.bytesSent||0)+(pair.bytesReceived||0),relay:report.get(pair.localCandidateId)?.candidateType==='relay'||report.get(pair.remoteCandidateId)?.candidateType==='relay',lost,jitterMs,rttMs:Number.isFinite(pair.currentRoundTripTime)?pair.currentRoundTripTime*1000:undefined});}catch{}}ledger.save();}
const referenceTranslations=new Map();
