let joiningLesson=false,lastJoinCode='';async function joinLesson(){const input=$('#lesson-code-input'),code=input.value.replace(/[０-９]/g,c=>String(c.charCodeAt(0)-65296)).trim();input.value=code;if(joiningLesson||!/^\d{4}$/.test(code))return;joiningLesson=true;lastJoinCode=code;$('#join-lesson').disabled=true;input.disabled=true;$('#join-status').textContent='授業に入っています…';const joinEpoch=sessionEpoch;try{const r=await api('/lessons/join',{code});if(tab!=='lesson'||sessionEpoch!==joinEpoch)return;await enter(r);$('#join-status').textContent='';}catch(e){await exitModeFullscreen();lastJoinCode='';$('#join-status').textContent=e.message;if(e.connectionIssue)showConnectionError(e);}finally{joiningLesson=false;input.disabled=false;$('#join-lesson').disabled=false;}}
